// BEEST figures for WordPress pages: [beest k=clean_now] etc. Reads BEEST 2's daily history.json,
// keeps the derived figures for 6 hours, and falls back to the last good set if the fetch fails.
function bz_beest_figs() {
	$f = get_transient( 'bz_beest_figs' );
	if ( is_array( $f ) ) { return $f; }
	$last = get_option( 'bz_beest_figs_last', array() );
	$r = wp_remote_get( 'https://beest.batcoinz.com/history.json', array( 'timeout' => 20 ) );
	if ( is_wp_error( $r ) ) { return $last; }
	$d = json_decode( wp_remote_retrieve_body( $r ), true );
	if ( empty( $d['rows'] ) ) { return $last; }
	$rows  = $d['rows'];
	$now   = end( $rows );
	$first = reset( $rows );
	// "Seven years ago" is the same calendar day, as on the BEEST chart pages.
	$then_date = ( new DateTime( $now['date'] ) )->modify( '-7 years' )->format( 'Y-m-d' );
	$then = $first;
	foreach ( $rows as $row ) { if ( $row['date'] === $then_date ) { $then = $row; break; } }
	$nt = new DateTime( $now['date'] ); $tt = new DateTime( $then['date'] ); $ft = new DateTime( $first['date'] );
	$f = array(
		'clean_now'   => number_format( 100 * $now['clean_share'], 1 ),
		'clean_start' => (string) round( 100 * $first['clean_share'] ),
		'start_month' => $ft->format( 'F Y' ),
		'month_now'   => $nt->format( 'F Y' ),
		'date_now'    => $nt->format( 'F j, Y' ),
		'date_then'   => $tt->format( 'F j, Y' ),
		'net_now'     => number_format( $now['net_mt'], 1 ),
		'net_then'    => number_format( $then['net_mt'], 1 ),
		'mit_mt'      => number_format( $now['mitigation_gas_mt_30d'], 2 ),
		'mit_pct'     => (string) round( 100 * $now['mitigation_gas_mt_30d'] / $now['gross_mt_30d'] ),
	);
	set_transient( 'bz_beest_figs', $f, 6 * HOUR_IN_SECONDS );
	update_option( 'bz_beest_figs_last', $f, false );
	return $f;
}
add_shortcode( 'beest', function ( $a ) {
	$a = shortcode_atts( array( 'k' => '' ), $a );
	$f = bz_beest_figs();
	return isset( $f[ $a['k'] ] ) ? esc_html( $f[ $a['k'] ] ) : '';
} );
// Pages that show live figures are cached for 6 hours at most, so the figures stay current.
